mapper.sql:
WHERE le.camp_id = #{campId}
AND le.occurred_at >= #{beginTime}
AND le.occurred_at < #{endTimeExclusive}
AND le.payment_type_id IN
#{paymentTypeId}
AND le.payment_way_id IN
#{paymentWayId}
AND om.room_id IN
#{roomId}
AND le.poi_id IN
#{poiId}
AND le.entry_type = 'income'
AND le.entry_type = 'expense'
AND le.source_type = 'order'
AND le.source_type != 'order'
AND ( CAST(le.ledger_entry_id AS CHAR) LIKE CONCAT('%', #{keyword}, '%') OR le.remark LIKE CONCAT('%', #{keyword}, '%') OR le.operator_name LIKE CONCAT('%', #{keyword}, '%') OR CAST(le.order_id AS CHAR) LIKE CONCAT('%', #{keyword}, '%') OR om.order_no LIKE CONCAT('%', #{keyword}, '%') OR om.out_order_no LIKE CONCAT('%', #{keyword}, '%') OR om.guest_name LIKE CONCAT('%', #{keyword}, '%') OR pt.payment_type_name LIKE CONCAT('%', #{keyword}, '%') OR pw.payment_way_name LIKE CONCAT('%', #{keyword}, '%') OR rc.name LIKE CONCAT('%', #{keyword}, '%') OR r.room_name LIKE CONCAT('%', #{keyword}, '%') )

mapper.select:
SELECT CAST(pt.payment_type_id AS CHAR) AS value, pt.payment_type_name AS label FROM payment_type pt WHERE pt.camp_id = #{campId} AND pt.status = 1 AND pt.is_deleted = 0
AND pt.is_income = #{isIncome}
ORDER BY pt.sort_no ASC, pt.payment_type_id ASC
